    "code": "/* Implementation of a stack in C */\n\n#include <stdio.h>\n#define MAX 10\n\nstruct Stack {\n    int top;\n    int items[MAX];\n};\n\nvoid initialize(struct Stack *s) {\n    s->top = -1;\n}\n\nvoid push(struct Stack *s, int val) {\n    if (s->top >= MAX-1) {\n        printf(\"Stack Overflow\\n\");\n        return;\n    }\n    s->items[++(s->top)] = val;\n}\n\nint pop(struct Stack *s) {\n    if (s->top == -1) {\n        printf(\"Stack Underflow\\n\");\n        return -1;\n    }\n    return s->items[s->top--];\n}\n\nvoid display(struct Stack s) {\n    if (s.top == -1) {\n        printf(\"Stack Underflow\\n\");\n        return;\n    }\n    printf(\"Displaying contents:\\n\");\n    for (int i=0; i<=s.top; i++) {\n        printf(\"%d\\n\", s.items[i]);\n    }\n}\n\nint main() {\n    struct Stack s;\n    initialize(&s);\n\n    int choice, value;\n\n    do {\n        printf(\"1. Push\\n\");\n        printf(\"2. Pop\\n\");\n        printf(\"3. Display\\n\");\n        printf(\"4. Exit\\n\");\n        printf(\"Enter your choice: \");\n        scanf(\"%d\", &choice);\n\n        switch (choice) {\n            case 1:\n                printf(\"Enter value to push: \");\n                scanf(\"%d\", &value);\n                push(&s, value);\n                break;\n            case 2:\n                value = pop(&s);\n                if (value != -1) {\n                    printf(\"Popped value: %d\\n\", value);\n                }\n                break;\n            case 3:\n                display(s);\n                break;\n            case 4:\n                printf(\"Exiting...\\n\");\n                break;\n            default:\n                printf(\"Invalid choice. Please try again.\\n\");\n        }\n    } while (choice != 4);\n\n    return 0;\n}",
