    "code": "/* Implemetation of Standard Queue*/\n\n#include <stdio.h>\n#define MAX 3\n\nstruct Queue\n{\n    int front;\n    int rear;\n    int items[MAX];\n};\n\nvoid initialize(struct Queue *q) {\n    q->front = -1;\n    q->rear = -1;\n}\n\nvoid enqueu(struct Queue *q, int val) {\n    if (q->rear >= MAX-1) {\n        printf(\"Queue Overflow\\n\");\n        return;\n    }\n    if (q->front == -1) q->front++;\n    q->items[++(q->rear)] = val;\n}\n\nint dequeu(struct Queue *q) {\n    if (q->front == -1 || q->front > q->rear) {\n        printf(\"Queue Underflow\\n\");\n        return -1;\n    }\n    return q->items[q->front++];\n}\n\nvoid display(struct Queue q) {\n    if (q.front == -1 || q.front > q.rear) {\n        printf(\"Queue Underflow\\n\");\n        return;\n    }\n    printf(\"Displaying Contents:\\n\");\n    for (int i=q.front; i<=q.rear; i++) {\n        printf(\"%d\\n\", q.items[i]);\n    }\n}\n\nint main() {\n    struct Queue q;\n    initialize(&q);\n\n    int choice, value;\n\n    do {\n        printf(\"1. Enqueue\\n\");\n        printf(\"2. Dequeue\\n\");\n        printf(\"3. Display\\n\");\n        printf(\"4. Exit\\n\");\n        printf(\"Enter your choice: \");\n        scanf(\"%d\", &choice);\n\n        switch (choice) {\n            case 1:\n                printf(\"Enter value to enqueue: \");\n                scanf(\"%d\", &value);\n                enqueu(&q, value);\n                break;\n            case 2:\n                value = dequeu(&q);\n                if (value != -1) {\n                    printf(\"Dequeued value: %d\\n\", value);\n                }\n                break;\n            case 3:\n                display(q);\n                break;\n            case 4:\n                printf(\"Exiting...\\n\");\n                break;\n            default:\n                printf(\"Invalid choice! Please try again.\\n\");\n        }\n    } while (choice != 4);\n\n    return 0;\n}\n",
