    "code": "/* Implementation of Singly Linked List in C */\n\n#include <stdio.h>\n#include <stdlib.h>\n\nstruct Node {\n    int data;\n    struct Node *next;\n};\n\nstruct Node *head = NULL;\n\nvoid insertAtBeginning() {\n    int val;\n    printf(\"Enter data : \");\n    scanf(\"%d\", &val);\n\n    struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));\n    newNode->data = val;\n    newNode->next = head;\n\n    if (head == NULL) {\n        head = newNode;\n        return;\n    }\n    newNode->next = head;\n    head = newNode;\n}\n\nvoid insertAtMiddle() {\n    int val, key, i;\n    printf(\"Enter data : \");\n    scanf(\"%d\", &val);\n    printf(\"Enter key : \");\n    scanf(\"%d\", &key);\n\n    struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));\n    newNode->data = val;\n    newNode->next = head;\n\n    if (head == NULL) {\n        printf(\"List is empty\\n\");\n        return;\n    }\n\n    struct Node *temp = head;\n    while (temp != NULL && temp->data != key) {\n        temp = temp->next;\n    }\n\n    if (temp == NULL) {\n        printf(\"key not found!\\n\");\n        return;\n    }\n\n    newNode->next = temp->next;\n    temp->next = newNode;\n}\n\nvoid insertAtEnd() {\n    int val;\n    printf(\"Enter data : \");\n    scanf(\"%d\", &val);\n\n    struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));\n    newNode->data = val;\n    newNode->next = NULL;\n\n    if (head == NULL) {\n        head = newNode;\n        return;\n    }\n    struct Node *temp = head;\n    while (temp->next != NULL) {\n        temp = temp->next;\n    }\n    temp->next = newNode;\n}\n\nvoid deleteAtBeginning() {\n    if (head == NULL) {\n        printf(\"List is empty\\n\");\n        return;\n    }\n    struct Node *temp = head;\n    head = head->next;\n    printf(\"Deleted element: %d\\n\", temp->data);\n    free(temp);\n}\n\nvoid deleteAtMiddle() {\n    if (head == NULL) {\n        printf(\"List is empty\\n\");\n        return;\n    }\n    int key;\n    printf(\"Enter key to delete : \");\n    scanf(\"%d\", &key);\n\n    if (head->data == key) {\n        struct Node *temp = head;\n        head = head->next;\n        printf(\"Deleted element: %d\\n\", temp->data);\n        free(temp);\n        return;\n    }\n\n    struct Node *temp = head;\n    while (temp->next != NULL && temp->next->data != key) {\n        temp = temp->next;\n    }\n    \n    if (temp->next == NULL) {\n        printf(\"Key not found!\\n\");\n        return;\n    }\n\n    struct Node *delNode = temp->next;\n    temp->next = delNode->next;\n    printf(\"Deleted element: %d\\n\", delNode->data);\n    free(delNode);\n}\n\nvoid deleteAtEnd() {\n    if (head == NULL) {\n        printf(\"List is empty\\n\");\n        return;\n    }\n    if (head->next == NULL) {\n        struct Node *temp = head;\n        head = NULL;\n        printf(\"Deleted element: %d\\n\", temp->data);\n        free(temp);\n    } else {\n        struct Node *temp = head;\n        while (temp->next->next != NULL) {\n            temp = temp->next;\n        }\n        struct Node *delNode = temp->next;\n        temp->next = NULL;\n        printf(\"Deleted element: %d\\n\", delNode->data);\n        free(delNode);\n    }\n}\n\nvoid display() {\n    if (head == NULL) {\n        printf(\"List is empty\\n\");\n        return;\n    }\n    struct Node *ptr = head;\n    printf(\"Linked List:\\n\");\n    while (ptr != NULL) {\n        printf(\"%d -> \", ptr->data);\n        ptr = ptr->next;\n    }\n    printf(\"NULL\\n\");\n}\n\nint main() {\n    int choice;\n\n    do {\n        printf(\"\\n- - - Linked List Menu - - -\\n\");\n        printf(\"1. Insert at Beginning\\n\");\n        printf(\"2. Insert at Middle\\n\");\n        printf(\"3. Insert at End\\n\");\n        printf(\"4. Delete at Beginning\\n\");\n        printf(\"5. Delete at Middle\\n\");\n        printf(\"6. Delete at End\\n\");\n        printf(\"7. Display List\\n\");\n        printf(\"8. Exit\\n\");\n        printf(\"Enter choice : \");\n        scanf(\"%d\", &choice);\n\n        switch (choice) {\n            case 1:\n                insertAtBeginning();\n                break;\n            case 2:\n                insertAtMiddle();\n                break;\n            case 3:\n                insertAtEnd();\n                break;\n            case 4:\n                deleteAtBeginning();\n                break;\n            case 5:\n                deleteAtMiddle();\n                break;\n            case 6:\n                deleteAtEnd();\n                break;\n            case 7:\n                display();\n                break;\n            case 8:\n                printf(\"Exiting...\\n\");\n                break;\n            default:\n                printf(\"Invalid choice! Please try again.\\n\");\n        }\n    } while (choice != 8);\n\n    return 0;\n}\n",
    "category": "Linked Lists"
