    "aim": "To construct a binary tree dynamically and implement Depth-First (Pre-order, In-order, Post-order) and Breadth-First (Level-order) traversals.",
    "algorithm": [
      "createTree(): Read value (-1 represents NULL). Create root node and recursively construct left and right subtrees.",
      "Pre-order: Visit Root -> Traverse Left -> Traverse Right.",
      "In-order: Traverse Left -> Visit Root -> Traverse Right.",
      "Post-order: Traverse Left -> Traverse Right -> Visit Root.",
      "Level-order: Enqueue root into standard FIFO queue. While queue is not empty, dequeue node, print data, and enqueue non-NULL children."
    ],
    "defaultStdin": "1\n2\n-1\n-1\n3\n-1\n-1",
    "output": "$ ./21_tree_traversals\nCreate the binary tree:\nEnter number (-1 for no node): 1\nEnter left child of 1:\nEnter number (-1 for no node): 2\nEnter left child of 2:\nEnter number (-1 for no node): -1\nEnter right child of 2:\nEnter number (-1 for no node): -1\nEnter right child of 1:\nEnter number (-1 for no node): 3\nEnter left child of 3:\nEnter number (-1 for no node): -1\nEnter right child of 3:\nEnter number (-1 for no node): -1\n\nPre-order: 1 2 3 \nIn-order: 2 1 3 \nPost-order: 2 3 1 \nLevel-order: 1 2 3 \n\nProcess finished with exit code 0",
    "code": "#include <stdio.h>\n#include <stdlib.h>\n\nstruct Node {\n    int data;\n    struct Node *left, *right;\n};\n\n// Create a new node\nstruct Node* createNode(int value) {\n    struct Node* newNode = malloc(sizeof(struct Node));\n\n    if (newNode == NULL) {\n        printf(\"Memory allocation failed!\\n\");\n        exit(1);\n    }\n\n    newNode->data = value;\n    newNode->left = NULL;\n    newNode->right = NULL;\n\n    return newNode;\n}\n\n// Create tree using integer input\nstruct Node* createTree() {\n    int value;\n\n    printf(\"Enter number (-1 for no node): \");\n    scanf(\"%d\", &value);\n\n    if (value == -1)\n        return NULL;\n\n    struct Node* root = createNode(value);\n\n    printf(\"Enter left child of %d:\\n\", value);\n    root->left = createTree();\n\n    printf(\"Enter right child of %d:\\n\", value);\n    root->right = createTree();\n\n    return root;\n}\n\n// Pre-order: Root, Left, Right\nvoid preorder(struct Node* root) {\n    if (root == NULL)\n        return;\n\n    printf(\"%d \", root->data);\n    preorder(root->left);\n    preorder(root->right);\n}\n\n// In-order: Left, Root, Right\nvoid inorder(struct Node* root) {\n    if (root == NULL)\n        return;\n\n    inorder(root->left);\n    printf(\"%d \", root->data);\n    inorder(root->right);\n}\n\n// Post-order: Left, Right, Root\nvoid postorder(struct Node* root) {\n    if (root == NULL)\n        return;\n\n    postorder(root->left);\n    postorder(root->right);\n    printf(\"%d \", root->data);\n}\n\n// Level-order traversal\nvoid levelorder(struct Node* root) {\n    if (root == NULL)\n        return;\n\n    struct Node* queue[100];\n    int front = 0, rear = 0;\n\n    queue[rear++] = root;\n\n    while (front < rear) {\n        struct Node* temp = queue[front++];\n        printf(\"%d \", temp->data);\n\n        if (temp->left != NULL)\n            queue[rear++] = temp->left;\n\n        if (temp->right != NULL)\n            queue[rear++] = temp->right;\n    }\n}\n\nint main() {\n    struct Node* root;\n\n    printf(\"Create the binary tree:\\n\");\n    root = createTree();\n\n    printf(\"\\nPre-order: \");\n    preorder(root);\n\n    printf(\"\\nIn-order: \");\n    inorder(root);\n\n    printf(\"\\nPost-order: \");\n    postorder(root);\n\n    printf(\"\\nLevel-order: \");\n    levelorder(root);\n\n    printf(\"\\n\");\n\n    return 0;\n}",
